function charge(s,n,label){const paid=Math.min(s.cash,n);s.cash-=paid;s.debt+=n-paid;s.ledger.push({day:s.day,pool:'life',label,amount:-paid,unpaid:n-paid});}
function nightly(s){if(!s.started||s.phase!=='play')return null;const notes=[];if(s.originObligation?.status==='pending'&&s.day>=s.originObligation.due){s.originObligation.status='missed';if(s.origin==='party'){const lost=Math.min(60,s.campaign,s.originRestrictedAllowance||0);s.campaign-=lost;spendOrigin(s,lost);s.supplies.volunteer=Math.max(0,s.supplies.volunteer-(s.originSupplies.volunteer||0));s.originSupplies.volunteer=0;s.relations.an=clamp(s.relations.an-6);if(lost)s.ledger.push({day:s.day,pool:'campaign',label:'提名時的活動失約，收回未用專款',amount:-lost});if(s.obligation==='pending')s.obligation='missed';notes.push('提名時答應的活動沒有出席。季安撤回 '+lost+' 未用專款與原配剩餘志工，生活現金不動。');}else{s.supplies.volunteer=Math.max(0,s.supplies.volunteer-(s.originSupplies.volunteer||0));s.originSupplies.volunteer=0;s.relations.yun=clamp(s.relations.yun-6);notes.push('街坊等的整理回覆沒有交回。阿芸失望，原配借調志工收回；認得你不等於能忽略約定。');}log(s,'起點帶來的約定沒有完成',notes.at(-1),s.origin==='party'?'hall':'market');}if(s.loan?.status==='pending'&&s.day>=s.loan.due){s.loan.status='missed';for(const k of ['print','volunteer'])s.supplies[k]=Math.max(0,s.supplies[k]-(s.loan.remaining?.[k]||0));s.relations.an=clamp(s.relations.an-4);notes.push('借設備時約好的整理工作沒有完成。季安收回尚有的借用物資，生活現金不受影響。');log(s,'借用約定沒有完成',notes.at(-1),'hall');}charge(s,DAILY_COST,'固定生活費');if(s.sharedObligation&&s.obligation==='pending'&&s.day>=s.obligationDue){s.obligation='missed';const lost=Math.min(60,s.campaign,(s.originRestrictedAllowance||0)+(s.partyRestrictedAllowance||0));s.campaign-=lost;spendOrigin(s,lost);s.ledger.push({day:s.day,pool:'campaign',label:'未出席約定活動，撤回未用支援',amount:-lost});s.supplies.volunteer=Math.max(0,s.supplies.volunteer-(s.partySupplies?.volunteer||0));s.partySupplies.volunteer=0;s.relations.an=clamp(s.relations.an-10);s.trust=clamp(s.trust-5);notes.push('你沒有出席答應的共同活動。季安撤回剩餘志工與最多 60 未用額度；這是失約的後果，不是對獨立立場的懲罰。');log(s,'一場沒出席的約定',notes.at(-1),'hall');}const uncorrected=s.promises.filter(p=>p.status==='pending');if(uncorrected.length){s.trust=clamp(s.trust-uncorrected.length*2);s.voters.forEach(v=>v.support=clamp(v.support-.006*uncorrected.length*v.precision,.025,.85));notes.push('有人又問起還沒說清楚的保證。它們沒有因為換一天就消失。');}
if(s.day===4){charge(s,RENT,'房租');s.rentPaid=true;s.day=5;s.phase='result';s.summary=finish(s);return{finished:true,notes};}s.day++;s.lifeLeft=DAY_SLOTS;s.dayActions=[];s.energy=clamp(s.energy+22);s.mood=clamp(s.mood-3);s.dailyEvent=dayEvent(s);s.shiftBonus=s.dailyEvent.bonus||0;const change=(rand(s.seed,800+s.day)-.5)*.025;s.voters.forEach(v=>v.turnout=clamp(v.turnout+change,.15,.95));s.external.push({day:s.day,news:s.dailyEvent.text,turnoutChange:change});rivalDay(s);s.polls.push(samplePoll(s));notes.push(s.dailyEvent.text);return{finished:false,notes};}
function finish(s){const tally=[0,0,0],counts=[0,0,0];let abstain=0;for(let i=0;i<s.voters.length;i++){const v=s.voters[i];if(rand(s.seed,1000,i)>=v.turnout){abstain++;continue;}let draw=rand(s.seed,1001,i),p=probs(v),picked=3;for(let k=0;k<4;k++){if(draw<p[k]){picked=k;break;}draw-=p[k];}if(picked===3)abstain++;else tally[picked]++;}s.choices.forEach(c=>counts[c.id]++);const max=Math.max(...tally),leaders=tally.map((x,i)=>x===max?i:-1).filter(i=>i>=0);const gaps=s.promises.filter(p=>p.status==='unresolved'||p.status==='pending').length,obligations=[s.originObligation?.status,s.origin==='party'?null:s.obligation,s.loan?.status].filter(x=>x&&x!=='none'),missed=obligations.filter(x=>x==='missed'||x==='pending').length,kept=obligations.filter(x=>x==='kept').length;let reflection=(gaps?'還有 '+gaps+' 項公開承諾未說清楚。':'沒有留下尚未釐清的公開保證。')+(missed?'另有 '+missed+' 份約定未履行。':kept?'你履行了 '+kept+' 份約定。':'這局沒有留下未履行的出席或回覆約定。')+(s.debt?'生活仍留下 '+s.debt+' 欠款；競選資源沒有替你補上。':'生活帳單已結清，剩下 '+s.cash+' 現金。');if(counts[0]>=3)reflection+=' 你多次親自把關；那些時間沒有同時拿去工作或拜訪。';if(counts[1]>=3)reflection+=' 你多次花時間談清楚界線，後續仍要靠行動維持。';if(counts[2]>=3)reflection+=' 你多次省下當下的時間，也接住了更多期待；這些紀錄不由選票替你消除。';return{tally,you:tally[0],rival:tally[1]+tally[2],abstain,total:tally.reduce((a,b)=>a+b,0),percent:tally.reduce((a,b)=>a+b,0)?Math.round(tally[0]/tally.reduce((a,b)=>a+b,0)*1000)/10:0,winner:leaders.length>1?'tie':leaders[0]===0?'you':RIVALS[leaders[0]-1].id,latentSupport:Math.round(average(s,'support')*100),turnoutIntent:Math.round(average(s,'turnout')*100),lastPoll:s.polls.at(-1),reflection,corrected:s.promises.filter(p=>p.status==='corrected').length,unresolved:s.promises.filter(p=>p.status==='unresolved'||p.status==='pending').length};}

function encounter(s,loc){if(!s.started||s.phase!=='play'||s.encounterDone[s.day])return null;const id=rand(s.seed,2100+s.day)<.5?'overtime':'equipment';if(id==='overtime'&&loc==='market'&&s.lifeLeft>=1&&s.dayActions.some(a=>a.id.startsWith('work')))return{id,title:'還有一車貨，你能留下嗎？',text:'這一班不是原本排好的。留下會擠掉一個行程；拒絕也沒有額外懲罰。',choices:[{id:0,title:'留下來多上一班',desc:'1 格、精神 −18、生活現金 +160。',time:1,energy:-18,cash:160},{id:1,title:'照原時間離開',desc:'不加錢、不扣體力，保留原本行程。',time:0,energy:0,cash:0}]};if(id==='equipment'&&loc==='hall'&&s.done.party&&s.obligation!=='pending'&&s.loan?.status!=='pending'&&!(s.originObligation?.kind==='party'&&s.originObligation.status==='pending'))return{id,title:'最後一套設備，還有人能借。',text:'季安願意借一份印刷包、一班志工，交換最晚明天（末日則今天）花 1 格一起整理居民問題。這是另一筆需要履行的約定。',choices:[{id:0,title:'借用，也答應整理工作',desc:'印刷包 +1、志工 +1；未來需 1 格、精神 −10。',time:0,energy:0,cash:0},{id:1,title:'婉拒，保留自己的時間',desc:'不拿資源、不新增義務。',time:0,energy:0,cash:0}]};return null;}
function resolveEncounter(s,loc,id){const e=encounter(s,loc),c=e?.choices.find(c=>c.id===id);if(!c||s.lifeLeft<c.time||s.energy+c.energy<0)return null;s.encounterDone[s.day]=e.id;s.lifeLeft-=c.time;s.energy=clamp(s.energy+c.energy);s.cash+=c.cash;if(c.cash)s.ledger.push({day:s.day,pool:'life',label:e.title,amount:c.cash});if(e.id==='equipment'&&id===0){s.supplies.print++;s.supplies.volunteer++;s.loan={day:s.day,due:Math.min(4,s.day+1),status:'pending',remaining:{print:1,volunteer:1}};}const text=c.title+'：'+c.desc;s.encounters.push({day:s.day,id:e.id,choice:id});log(s,e.title,text,loc);return{title:e.title,result:text};}

function routineAction(s,plan){const all=actions(s);if(plan==='promise'){const joint=all.find(c=>(c.id==='joint'||c.id==='origin-reply')&&canAction(s,c,false));if(joint)return joint;}if(plan==='work'){const work=all.find(c=>c.id===(s.lifeLeft>=2?'work-full':'work-short')&&canAction(s,c,false));if(work)return work;}if(plan==='records'){const record=all.find(c=>c.id==='records'&&canAction(s,c,false));if(record)return record;}return all.find(c=>c.id==='rest'&&canAction(s,c,false))||null;}
